with feeders as (
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_NO))) as HUB_QUOTE_HK
        , coalesce(nullif(trim(PREMIUM_TYPE), ''), '') as PREMIUM_TYPE
        , coalesce(nullif(trim(SI_AGE_BAND), ''), '') as SUM_INSURED_SLAB
        , 'ABOVE-80' as AGE_BAND_CODE
        , ABOVE_80 as AGE_BAND_PREMIUM_RATE
        , 'BJAZ_GRP_HLT_PREMIUM_DTLS_TYP1' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_premium_dtls_typ1') }}
    where (nullif(trim(QUOTE_NO),'')) is not null
),

resolved as (
    select
        HUB_QUOTE_HK,
        PREMIUM_TYPE,
        SUM_INSURED_SLAB,
        AGE_BAND_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then AGE_BAND_PREMIUM_RATE end) as AGE_BAND_PREMIUM_RATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_QUOTE_HK, PREMIUM_TYPE, SUM_INSURED_SLAB, AGE_BAND_CODE
),

hashed as (
    select
        *,
        case when PREMIUM_TYPE is not null or SUM_INSURED_SLAB is not null or AGE_BAND_CODE is not null or AGE_BAND_PREMIUM_RATE is not null
                     then md5(upper(coalesce(cast(PREMIUM_TYPE as varchar), '') || '|' || coalesce(cast(SUM_INSURED_SLAB as varchar), '') || '|' || coalesce(cast(AGE_BAND_CODE as varchar), '') || '|' || coalesce(cast(AGE_BAND_PREMIUM_RATE as varchar), '')))
                end as SAT_QUOTE_PREMIUM_RATE_AGE_BAND_HASHDIFF
    from resolved
)

select * from hashed
where HUB_QUOTE_HK is not null
  and SAT_QUOTE_PREMIUM_RATE_AGE_BAND_HASHDIFF is not null
